    generarIdConConsecutivo,
    generarIdError,
    limpiarTexto,
    limpiarDetalle,
    detalleComoJson,
    debeAlertar,
    filaLogErrores,
    workflowDesdeNombre,
    tipoErrorDesdeNodo,
    analizarErrorTrigger,
  };
}

